let permissions=[];let seq=0;
Object.entries(raw).forEach(([module,names])=>names.split('|').filter(Boolean).forEach(name=>permissions.push({id:`p${++seq}`,module,name,type:'permission'})));
Object.entries(screens).forEach(([screen,subs])=>{const parent=`p${++seq}`;permissions.push({id:parent,module:'PANTALLAS',name:screen,type:'global',screen});subs.split('|').filter(Boolean).forEach(name=>permissions.push({id:`p${++seq}`,module:'PANTALLAS',name,type:'sub',screen,parent}));});
// Complementos del catálogo reorganizado recibido en ACCIONES.docx.
// Se agregan al final para conservar los identificadores y el avance ya guardado.
['Ver desglose de otros empleados','Ver el desglose de la empresa'].forEach(name=>permissions.push({id:`p${++seq}`,module:'ACCIONES · DESGLOSES',name,type:'permission'}));
['Eliminar visita del Walkin Manager','Promover visitas del Walkin Manager'].forEach(name=>permissions.push({id:`p${++seq}`,module:'ACCIONES · WALKIN MANAGER',name,type:'permission'}));
const visitNoteActions=['Change Historical Visit Notes','Change Other Employee Visit Notes','Change Own Visit Notes','Create Historical Visit Notes','Create Visit Notes','Delete Other Employee Visit Notes','Delete Own Visit Notes','View Other Employee Visit Notes'];
['ANULACIÓN','CAMBIOS','CUENTAS','FOLIO AUTORIZACIÓN','VALES DE REGALO','VISIT NOTES'].forEach(noteType=>visitNoteActions.forEach(name=>permissions.push({id:`p${++seq}`,module:`VISIT NOTE TYPES · ${noteType}`,name,type:'permission'})));
const horarioGlobal=permissions.find(p=>p.module==='PANTALLAS'&&p.type==='global'&&p.screen==='Horario');
['Importar/Exportar','Informes','Internet'].forEach(name=>permissions.push({id:`p${++seq}`,module:'PANTALLAS',name,type:'sub',screen:'Horario',parent:horarioGlobal.id}));
// Los bloques anteriores quedan conservados solo para no perder datos guardados,
// pero ya no se muestran ni se contabilizan porque el documento nuevo los sustituye.
permissions.filter(p=>['VISIT NOTE TYPES','REPORTS','REPORTES'].includes(p.module)).forEach(p=>p.deprecated=true);
const defaultsDeny=new Set(['Eliminar cita','Modificar coste de cancelación','Actualizar puntos de cliente','Cancel Membership','Eliminar cliente','Refund Membership','Resubscribe Membership','Suspend Membership','Waive Membership','Cambiar comisiones del empleado','Cambiar detalles de empleados','Eliminar habilidades','Añadir entrada del horario','Cambiar horas actuales','Cambiar horas programadas','Eliminar entrada del horario','Borrar una transacción','Reembolsar transacción','Activar o desactivar seguridad','Borrar el registro','Cambiar el PIN de otro empleado','Cambiar huella de otro empleado','Can Upgrade','Change own PIN','Conectar y desconectar otros empleados','Configurar la contraseña de inicio','Huella dactilar puede ser asignada','Cambiar detalles de bonos','Cambiar detalles de servicios','Cambiar precio servicio','Cambiar servicios de habilidades','Cambiar cantidad de stock','Cambiar código de barras del producto','Cambiar configuración de reorder','Cambiar coste medio','Cambiar detalles de stock','Cambiar el precio de venta de producto','Cambiar precio de compra del producto','Crear productos','Change Other Employee Visit Notes','Delete Other Employee Visit Notes']);
const stockReports=new Set(['Stock: Etiquetas de producto para estanterías','Stock: Formulario de artículos no listados','Stock: Historial de movimientos de stock','Stock: Listado de precios de productos','Stock: Pedidos pendientes','Stock: Stock recibido','Stock: Sumario de stock recibido']);
let state=appCore?appCore.matrix.loadLocal():{};
if(!state.values)state.values={};if(!state.groups)state.groups={};
function ensureDefaults(){permissions.forEach(p=>{const k=`Control de Stock|${p.id}`;if(state.values[k]===undefined){if(p.module==='ITEMS / REPORTES')state.values[k]=stockReports.has(p.name)?'allow':'deny';else if(p.module==='PANTALLAS')state.values[k]=p.type==='global'?(p.name==='Stock'?'allow':'deny'):null;else state.values[k]=defaultsDeny.has(p.name)?'deny':'allow';}});const applyConfirmedRules=(state.groupRulesVersion||0)<GROUP_RULES_VERSION;EMPLOYEE_GROUPS.forEach(g=>{if(applyConfirmedRules||!state.groups[g.id])state.groups[g.id]=g.defaultProfile});if(applyConfirmedRules)state.groupRulesVersion=GROUP_RULES_VERSION;return applyConfirmedRules}
ensureDefaults();
let currentProfile=state.currentProfile||PROFILES[0],moduleFilter='all',statusFilter='all',search='',matrixSearchText='';
const $=s=>document.querySelector(s),esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function value(p){return state.values[`${currentProfile}|${p.id}`]||null}function blocked(p){return p.type==='sub'&&state.values[`${currentProfile}|${p.parent}`]==='deny'}
let cloudReady=false,activeUser=null,cloudSaveTimer=null,cloudSaveRunning=false,cloudSaveQueued=false;
function setCloudStatus(text,kind=''){$('#cloudStatus').textContent=text;$('#cloudStatus').className=`cloud-status ${kind}`.trim()}
function saveLocal(){state.currentProfile=currentProfile;appCore?.matrix.saveLocal(state);$('#saveStatus').textContent='Guardado ahora';setTimeout(()=>$('#saveStatus').textContent=cloudReady?'Guardado en la nube':'Guardado en este dispositivo',1400)}
function scheduleCloudSave(){if(!cloudReady||!activeUser)return;clearTimeout(cloudSaveTimer);setCloudStatus('Cambios pendientes…');cloudSaveTimer=setTimeout(()=>saveToCloud(true),700)}
function save(){saveLocal();scheduleCloudSave()}
async function saveToCloud(silent=false){
  if(!cloudReady||!activeUser){if(!silent)toast('Guardado solamente en este dispositivo');return false}
  if(cloudSaveRunning){cloudSaveQueued=true;return false}
  cloudSaveRunning=true;setCloudStatus('Guardando en la nube…');
  const {error}=await appCore.matrix.saveCloud(state,activeUser.id);
  cloudSaveRunning=false;
  if(error){setCloudStatus('No se pudo guardar','error');if(!silent)toast('No se pudo guardar en la nube');return false}
  setCloudStatus('Guardado en la nube','saved');$('#saveStatus').textContent='Guardado en la nube';if(!silent)toast('Cambios guardados en la nube');
  if(cloudSaveQueued){cloudSaveQueued=false;saveToCloud(true)}
  return true
}
function countsAsRequired(p){return !p.deprecated&&!blocked(p)}
function filtered(){return permissions.filter(p=>!p.deprecated&&(moduleFilter==='all'||p.module===moduleFilter)&&(!search||`${p.name} ${p.module} ${p.screen||''}`.toLowerCase().includes(search))&&(statusFilter==='all'||(statusFilter==='pending'&&!value(p)&&countsAsRequired(p))||value(p)===statusFilter))}
function render(){const list=filtered();$('#resultCount').textContent=`${list.length} ${list.length===1?'permiso':'permisos'}`;$('#contextHint').textContent=moduleFilter==='all'?'Mostrando el catálogo completo':`Filtrado por ${moduleFilter}`;let html='',last='';list.forEach(p=>{if(p.module!==last){last=p.module;html+=`<h3 class="module-heading">${esc(last)} <span>${list.filter(x=>x.module===last).length}</span></h3>`}const v=value(p),isBlocked=blocked(p);html+=`<article class="card ${p.type==='global'?'global':''} ${p.type==='sub'?'child':''} ${isBlocked?'disabled':''}"><div><div class="permission-name">${p.type==='sub'?'↳ ':''}${esc(p.name)}</div><div class="permission-meta">${p.type==='global'?'<span class="global-tag">Acceso global a pantalla</span>':p.type==='sub'?`Subpermiso de ${esc(p.screen)}`:esc(p.module)}</div></div><div class="choices"><button class="choice allow ${v==='allow'?'selected':''}" data-id="${p.id}" data-v="allow" ${isBlocked?'disabled':''}>✓ Aplica</button><button class="choice deny ${v==='deny'?'selected':''}" data-id="${p.id}" data-v="deny" ${isBlocked?'disabled':''}>× Sin acceso</button></div></article>`});$('#permissionList').innerHTML=html;$('#emptyState').hidden=!!list.length;updateSummary()}
function updateSummary(){const required=permissions.filter(countsAsRequired),defined=required.filter(p=>value(p));const pct=required.length?Math.round(defined.length/required.length*100):100;$('#profileTitle').textContent=currentProfile;$('#progressText').textContent=`${defined.length} de ${required.length} permisos necesarios definidos`;$('#progressPct').textContent=`${pct}%`;$('#progressRing').style.setProperty('--p',pct)}
function renderGroups(){const assigned=EMPLOYEE_GROUPS.filter(g=>state.groups[g.id]).length;$('#groupsAssigned').textContent=`${assigned} de ${EMPLOYEE_GROUPS.length}`;$('#groupsGrid').innerHTML=EMPLOYEE_GROUPS.map((g,i)=>`<article class="group-card ${state.groups[g.id]?'configured':''}"><div class="group-icon">${i+1}</div><div><h3>${esc(g.name)}</h3><p class="group-description">${esc(g.description)}</p><div class="group-details"><span><strong>${g.employees}</strong> empleados actuales</span><span>Nivel anterior: <strong>${esc(g.previous)}</strong></span></div><label class="field"><span>Perfil predeterminado</span><select class="group-profile" data-group="${g.id}"><option value="">Seleccionar perfil…</option>${PROFILES.map(p=>`<option value="${esc(p)}" ${state.groups[g.id]===p?'selected':''}>${esc(p)}</option>`).join('')}</select></label></div></article>`).join('')}
function permissionTitle(p){if(p.module==='PANTALLAS')return 'PANTALLAS';if(p.module==='ITEMS / REPORTES')return 'ÍTEMS / REPORTES';if(p.module.startsWith('VISIT NOTE TYPES'))return 'VISIT NOTE TYPES';return 'ACCIONES'}
function permissionSubtitle(p){if(p.module==='PANTALLAS')return p.screen||p.name;if(p.module==='ITEMS / REPORTES')return p.name.includes(':')?p.name.split(':')[0]:'Reportes';return p.module.includes(' · ')?p.module.split(' · ').slice(1).join(' · '):p.module}
function matrixValue(profile,p){return state.values[`${profile}|${p.id}`]||null}
function matrixBlocked(profile,p){return p.type==='sub'&&state.values[`${profile}|${p.parent}`]==='deny'}
function globalControls(scope,key,profile){return `<div class="matrix-global"><button data-global-scope="${scope}" data-global-key="${esc(key)}" data-profile="${esc(profile)}" data-v="allow" title="Marcar todo como Aplica">A</button><button data-global-scope="${scope}" data-global-key="${esc(key)}" data-profile="${esc(profile)}" data-v="deny" title="Marcar todo como Sin acceso">N</button></div>`}
function renderMatrix(){const titleOrder=['ACCIONES','ÍTEMS / REPORTES','VISIT NOTE TYPES','PANTALLAS'];const visible=permissions.map((p,i)=>({p,i})).filter(x=>!x.p.deprecated&&(!matrixSearchText||`${permissionTitle(x.p)} ${permissionSubtitle(x.p)} ${x.p.name}`.toLowerCase().includes(matrixSearchText))).sort((a,b)=>titleOrder.indexOf(permissionTitle(a.p))-titleOrder.indexOf(permissionTitle(b.p))||permissionSubtitle(a.p).localeCompare(permissionSubtitle(b.p),'es')||a.i-b.i).map(x=>x.p);let html=`<div class="matrix-row matrix-head"><div>Título / subtítulo</div><div>Permiso</div>${PROFILES.map(p=>`<div>${esc(p)}</div>`).join('')}</div>`;let lastTitle='',lastSubtitle='';visible.forEach(p=>{const title=permissionTitle(p),subtitle=permissionSubtitle(p);if(title!==lastTitle){lastTitle=title;lastSubtitle='';html+=`<div class="matrix-row title-row"><div>${esc(title)}<small>Selección global por título</small></div><div>Todo el título</div>${PROFILES.map(profile=>`<div>${globalControls('title',title,profile)}</div>`).join('')}</div>`}if(subtitle!==lastSubtitle){lastSubtitle=subtitle;html+=`<div class="matrix-row subtitle-row"><div>${esc(subtitle)}<small>Selección global por subtítulo</small></div><div>Todo el subtítulo</div>${PROFILES.map(profile=>`<div>${globalControls('subtitle',`${title}||${subtitle}`,profile)}</div>`).join('')}</div>`}html+=`<div class="matrix-row permission-row"><div>${esc(subtitle)}</div><div>${p.type==='global'?'<b>Acceso global:</b> ':p.type==='sub'?'↳ ':''}${esc(p.name)}</div>${PROFILES.map(profile=>{const inherited=matrixBlocked(profile,p),v=inherited?'deny':matrixValue(profile,p);return `<div><div class="matrix-choice-pair ${inherited?'inherited':''}"><button class="matrix-option allow ${v==='allow'?'selected':''}" data-matrix-id="${p.id}" data-profile="${esc(profile)}" data-matrix-v="allow" ${inherited?'disabled':''} title="Aplica">A</button><button class="matrix-option deny ${v==='deny'?'selected':''}" data-matrix-id="${p.id}" data-profile="${esc(profile)}" data-matrix-v="deny" ${inherited?'disabled':''} title="Sin acceso">N</button></div></div>`}).join('')}</div>`});$('#matrixGrid').innerHTML=html}
function showView(view){const groups=view==='groups',matrix=view==='matrix',home=view==='home';$('#homeView').hidden=!home;$('#permissionsView').hidden=view!=='permissions';$('#groupsView').hidden=!groups;$('#matrixView').hidden=!matrix;$('#adminView').hidden=true;document.querySelectorAll('.view-tab').forEach(b=>b.classList.remove('active'));$('#homeTab').classList.toggle('active',home);$('#permissionsTab').classList.toggle('active',view==='permissions');$('#groupsTab').classList.toggle('active',groups);$('#matrixTab').classList.toggle('active',matrix);if(groups)renderGroups();if(matrix)renderMatrix()}
async function showOwnedArea(type,section,button){$('#homeView').hidden=true;$('#permissionsView').hidden=true;$('#groupsView').hidden=true;$('#matrixView').hidden=true;$('#adminView').hidden=false;$('#homeTab').classList.remove('active');document.querySelectorAll('.view-tab').forEach(b=>b.classList.remove('active'));button.classList.add('active');await loadAdmin();showConfigType(type);if(type==='rh')showAdminSection(section||'employees')}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
PROFILES.forEach(p=>$('#profileSelect').add(new Option(p,p)));$('#profileSelect').value=currentProfile;[...new Set(permissions.filter(p=>!p.deprecated).map(p=>p.module))].forEach(m=>$('#moduleSelect').add(new Option(m,m)));
['Todos','Pendientes','PANTALLAS','AGENDA','CLIENTES','STOCK','ITEMS / REPORTES'].forEach((t,i)=>{const b=document.createElement('button');b.className='tab'+(i===0?' active':'');b.textContent=t;b.dataset.m=t==='Todos'||t==='Pendientes'?'all':t;b.dataset.pending=t==='Pendientes';$('#quickTabs').append(b)});
