$('#profileSelect').onchange=e=>{currentProfile=e.target.value;save();render()};$('#moduleSelect').onchange=e=>{moduleFilter=e.target.value;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.m===moduleFilter&&!x.dataset.pending));render()};$('#statusSelect').onchange=e=>{statusFilter=e.target.value;render()};$('#searchInput').oninput=e=>{search=e.target.value.trim().toLowerCase();render()};
