$('#matrixGrid').addEventListener('click',e=>{const global=e.target.closest('[data-global-scope]');if(global){const profile=global.dataset.profile,val=global.dataset.v,scope=global.dataset.globalScope,key=global.dataset.globalKey;const targets=permissions.filter(p=>!p.deprecated&&(scope==='title'?permissionTitle(p)===key:`${permissionTitle(p)}||${permissionSubtitle(p)}`===key));targets.forEach(p=>state.values[`${profile}|${p.id}`]=val);save();renderMatrix();toast(`${targets.length} permisos actualizados para ${profile}`);return}const cell=e.target.closest('[data-matrix-id]');if(!cell)return;state.values[`${cell.dataset.profile}|${cell.dataset.matrixId}`]=cell.dataset.matrixV;save();renderMatrix();toast(cell.dataset.matrixV==='allow'?'Marcado: Aplica':'Marcado: Sin acceso')});
function bulk(v){const list=filtered().filter(p=>!blocked(p));if(!list.length)return;list.forEach(p=>state.values[`${currentProfile}|${p.id}`]=v);save();render();toast(`${list.length} permisos actualizados`)}$('#allAllow').onclick=()=>bulk('allow');$('#allDeny').onclick=()=>bulk('deny');

async function connectCloud(user){
  activeUser=user;$('#loginOverlay').hidden=true;$('#logoutBtn').hidden=false;setCloudStatus('Cargando nube…');
  const {data,error}=await appCore.matrix.loadCloud();
  if(error){setCloudStatus('Error de conexión','error');toast('No se pudo cargar la base de datos');return}
  if(!appCore.matrix.hasCloudData(data.datos)){$('#firstSyncOverlay').hidden=false;setCloudStatus('Primera sincronización pendiente');return}
  const selectedProfile=currentProfile;
  state.values=data.datos.values||{};state.groups=data.datos.groups||{};state.homeLayout=data.datos.homeLayout||state.homeLayout||{};state.groupRulesVersion=data.datos.groupRulesVersion||0;HomeMap.setLayout(state.homeLayout);const groupRulesUpdated=ensureDefaults();currentProfile=selectedProfile;saveLocal();
  cloudReady=true;render();renderGroups();setCloudStatus('Conectado y actualizado','saved');$('#saveStatus').textContent='Guardado en la nube';if(groupRulesUpdated)scheduleCloudSave()
}
async function initCloud(){
  if(!appCore){setCloudStatus('Conexión no disponible','error');$('#loginMessage').textContent='No se pudo cargar la conexión segura.';return}
  const {user}=await appCore.auth.restoreSession();
  if(user)await connectCloud(user);else{$('#loginOverlay').hidden=false;setCloudStatus('Inicia sesión')}
}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=$('#loginBtn');button.disabled=true;button.textContent='Entrando…';$('#loginMessage').textContent='';const {user,error}=await appCore.auth.signIn($('#loginEmail').value.trim(),$('#loginPassword').value);button.disabled=false;button.textContent='Entrar';if(error){$('#loginMessage').textContent='No pudimos entrar. Revisa el correo y la contraseña.';return}$('#loginPassword').value='';await connectCloud(user)};
$('#uploadFirstBtn').onclick=async()=>{cloudReady=true;$('#firstSyncOverlay').hidden=true;const ok=await saveToCloud(false);if(!ok){cloudReady=false;$('#firstSyncOverlay').hidden=false}};
$('#syncLaterBtn').onclick=()=>{$('#firstSyncOverlay').hidden=true;setCloudStatus('Nube pendiente','error');toast('El avance continúa guardado solo en este dispositivo')};
$('#logoutBtn').onclick=async()=>{await appCore.auth.signOut();cloudReady=false;activeUser=null;$('#logoutBtn').hidden=true;$('#loginOverlay').hidden=false;setCloudStatus('Sesión cerrada');toast('Sesión cerrada')};
let adminData={departamentos:[],puestos:[],perfiles:[],sucursales:[],empleados:[]},adminLoaded=false,adminSection='employees',configType='rh';
let employeeFilters={search:'',department:'',branch:'',status:''};
const safe=s=>esc(String(s??''));
function adminOption(value,label,selected){return `<option value="${safe(value)}" ${value===selected?'selected':''}>${safe(label)}</option>`}
function setAdminStatus(text,kind=''){$('#adminStatus').textContent=text;$('#adminStatus').className=`admin-status ${kind}`.trim()}
async function loadAdmin(force=false){if(!activeUser){setAdminStatus('Inicia sesión para consultar la configuración.','error');return}if(adminLoaded&&!force){renderAdmin();return}setAdminStatus('Cargando información administrativa…');const {data,error}=await appCore.admin.load();if(error){setAdminStatus('No se pudo cargar este apartado. Revisa la conexión e inténtalo nuevamente.','error');return}adminData=data||adminData;adminLoaded=true;setAdminStatus('Información actualizada desde la nube.');renderAdmin()}
function employeeStatus(e){if(e==='SUSPENDIDO_TEMPORAL')return '<span class="status-pill suspended">Suspensión temporal</span>';if(e==='TERMINADO')return '<span class="status-pill ended">Terminado</span>';return '<span class="status-pill">Activo</span>'}
function adminDate(v){if(!v)return 'Fecha de ingreso pendiente';const [y,m,d]=String(v).split('-');return y&&m&&d?`Ingreso: ${d}/${m}/${y}`:`Ingreso: ${v}`}
function filterText(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function renderAdminEmployees(){const all=adminData.empleados||[],departments=[...new Set(all.map(e=>e.departamento).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),branches=[...new Set(all.map(e=>e.sucursal).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es')),term=filterText(employeeFilters.search),rows=all.filter(e=>{const haystack=filterText([e.nombres,e.apellido_paterno,e.apellido_materno,e.numero_empleado,e.correo,e.telefono,e.puesto,e.profesion,e.perfil].join(' '));return(!term||haystack.includes(term))&&(!employeeFilters.department||e.departamento===employeeFilters.department)&&(!employeeFilters.branch||e.sucursal===employeeFilters.branch)&&(!employeeFilters.status||e.estado===employeeFilters.status)});$('#adminEmployees').innerHTML=`<div class="admin-list-header"><div><h3>Plantilla de empleados</h3><p>Mostrando ${rows.length} de ${all.length} empleados</p></div></div><div class="employee-filters" aria-label="Filtros de empleados"><label class="employee-search"><span>Buscar empleado</span><input data-employee-filter="search" type="search" value="${safe(employeeFilters.search)}" placeholder="Nombre, correo, puesto o perfil"></label><label><span>Departamento</span><select data-employee-filter="department"><option value="">Todos</option>${departments.map(x=>adminOption(x,x,employeeFilters.department)).join('')}</select></label><label><span>Sucursal</span><select data-employee-filter="branch"><option value="">Todas</option>${branches.map(x=>adminOption(x,x,employeeFilters.branch)).join('')}</select></label><label><span>Estado</span><select data-employee-filter="status">${adminOption('','Todos',employeeFilters.status)}${adminOption('ACTIVO','Activo',employeeFilters.status)}${adminOption('SUSPENDIDO_TEMPORAL','Suspensión temporal',employeeFilters.status)}${adminOption('TERMINADO','Terminado',employeeFilters.status)}</select></label><button class="clear-employee-filters" data-clear-employee-filters ${Object.values(employeeFilters).some(Boolean)?'':'disabled'}>Limpiar filtros</button></div><div class="admin-table"><div class="admin-row head"><div>Empleado</div><div>Área laboral</div><div>Ubicación</div><div>Perfil de seguridad</div><div>Acción</div></div>${rows.length?rows.map(e=>`<div class="admin-row"><div><strong>${safe([e.nombres,e.apellido_paterno,e.apellido_materno].filter(Boolean).join(' '))}</strong><small>${safe(e.numero_empleado)} · ${safe(e.correo||'Correo pendiente')} · ${safe(e.telefono||'Teléfono pendiente')}</small></div><div><strong>${safe(e.departamento||'Sin departamento')} · ${safe(e.puesto||'Sin puesto')}</strong><small>Profesión: ${safe(e.profesion||'Pendiente')} · ${safe(adminDate(e.fecha_ingreso))}</small></div><div><strong>${safe(e.region||'Región MTY')}</strong><small>Sucursal ${safe(e.sucursal||'pendiente')} · ${employeeStatus(e.estado)}</small></div><div><strong>${safe(e.perfil||'Sin asignar')}</strong><small>Matriz de Seguridad</small></div><div><button class="edit-admin" data-edit-employee="${safe(e.id)}">Editar</button></div></div>`).join(''):'<div class="admin-empty">No hay empleados que coincidan con estos filtros.</div>'}</div>`}
function renderAdminDepartments(){const rows=adminData.departamentos||[];$('#adminDepartments').innerHTML=`<div class="admin-list-header"><div><h3>Departamentos</h3><p>Área y departamento se administran en un solo catálogo.</p></div><button class="button primary" data-new-catalog="department">+ Nuevo departamento</button></div><div class="admin-table"><div class="admin-row catalog head"><div>Código</div><div>Nombre</div><div>Descripción</div><div>Acción</div></div>${rows.length?rows.map(d=>`<div class="admin-row catalog"><div><strong>${safe(d.codigo)}</strong></div><div>${safe(d.nombre)}</div><div>${safe(d.descripcion||'Sin descripción')}</div><div><button class="edit-admin" data-edit-department="${safe(d.id)}">Editar</button></div></div>`).join(''):'<div class="admin-empty">No hay departamentos registrados.</div>'}</div>`}
function renderAdminPositions(){const rows=adminData.puestos||[];$('#adminPositions').innerHTML=`<div class="admin-list-header"><div><h3>Puestos laborales</h3><p>Los puestos son distintos de los perfiles de seguridad.</p></div><button class="button primary" data-new-catalog="position">+ Nuevo puesto</button></div><div class="admin-table"><div class="admin-row catalog head"><div>Código</div><div>Nombre</div><div>Clasificación / departamento</div><div>Acción</div></div>${rows.length?rows.map(p=>`<div class="admin-row catalog"><div><strong>${safe(p.codigo)}</strong></div><div>${safe(p.nombre)}</div><div><strong>${safe(p.clasificacion)}</strong><small>${safe(p.departamento||'Sin departamento')}</small></div><div><button class="edit-admin" data-edit-position="${safe(p.id)}">Editar</button></div></div>`).join(''):'<div class="admin-empty">No hay puestos registrados.</div>'}</div>`}
function securityPermissionStatus(profile,p){if(p.type==='sub'&&state.values[`${profile}|${p.parent}`]==='deny')return 'deny';return state.values[`${profile}|${p.id}`]||'pending'}
function renderAdminProfiles(){const dbProfiles=adminData.perfiles||[],profileNames=[...new Set([...PROFILES,...dbProfiles.map(p=>p.nombre).filter(Boolean)])];const activePermissions=permissions.filter(p=>!p.deprecated);$('#adminProfiles').innerHTML=`<div class="config-heading"><div><h3>Mapa de usuarios y permisos</h3><p><strong>Propietario: Seguridad.</strong> Abre cada perfil para consultar sus grupos, usuarios y todos los permisos heredados desde la matriz.</p></div><span class="status-pill">${profileNames.length} perfiles</span></div><div class="security-map-root"><div class="security-root-node"><span>◆</span><div><strong>Usuarios y permisos</strong><small>Perfiles de seguridad</small></div></div><div class="security-profile-tree">${profileNames.map(profile=>{const groups=EMPLOYEE_GROUPS.filter(g=>state.groups[g.id]===profile),users=(adminData.empleados||[]).filter(e=>e.perfil===profile),totals={allow:0,deny:0,pending:0};activePermissions.forEach(p=>totals[securityPermissionStatus(profile,p)]++);return `<details class="security-profile-branch"><summary><span class="branch-toggle">+</span><div class="profile-map-title"><strong>${safe(profile)}</strong><small>${groups.length} grupos · ${users.length} usuarios · ${activePermissions.length} permisos</small></div><div class="profile-map-counts"><span class="allow">${totals.allow} Aplica</span><span class="deny">${totals.deny} Sin acceso</span><span class="pending">${totals.pending} Pendientes</span></div></summary><div class="security-branch-content"><section class="security-map-section"><h4>Grupos asignados</h4><div class="security-chip-list">${groups.length?groups.map(g=>`<span>${safe(g.name)}</span>`).join(''):'<em>Sin grupos asignados</em>'}</div></section><section class="security-map-section"><h4>Usuarios con este perfil</h4><div class="security-user-list">${users.length?users.map(u=>`<article><strong>${safe([u.nombres,u.apellido_paterno,u.apellido_materno].filter(Boolean).join(' '))}</strong><small>${safe(u.sucursal||'Sucursal pendiente')} · ${safe(u.puesto||'Puesto pendiente')}</small></article>`).join(''):'<em>Sin usuarios asignados</em>'}</div></section><details class="permission-map-details"><summary><span>+</span> Ver los ${activePermissions.length} permisos de ${safe(profile)}</summary><div class="permission-map-list">${activePermissions.map(p=>{const status=securityPermissionStatus(profile,p),label=status==='allow'?'Aplica':status==='deny'?'Sin acceso':'Pendiente';return `<div class="permission-map-row"><div><strong>${safe(p.name)}</strong><small>${safe(p.module)}${p.screen?` · ${safe(p.screen)}`:''}</small></div><span class="permission-state ${status}">${label}</span></div>`}).join('')}</div></details><button class="open-profile-permissions" data-open-profile="${safe(profile)}">Abrir y modificar este perfil</button></div></details>`}).join('')}</div></div>`}
function countEmployeesByBranch(id){return (adminData.empleados||[]).filter(e=>e.sucursal_id===id).length}
function renderRegionalConfig(){const branches=adminData.sucursales||[];$('#regionalConfig').innerHTML=`<div class="config-heading"><div><h3>Configuración de sucursales</h3><p>Estructura territorial normalizada para definir configuraciones generales y excepciones.</p></div><span class="status-pill">${branches.length} sucursales</span></div><div class="regional-hierarchy" aria-label="Jerarquía de configuración territorial"><article class="scope-level global"><span>1</span><div><strong>Global</strong><small>Configuración base de toda la organización</small></div></article><b>→</b><article class="scope-level state"><span>2</span><div><strong>Nuevo León</strong><small>Configuración del estado</small></div></article><b>→</b><article class="scope-level city"><span>3</span><div><strong>Monterrey</strong><small>Configuración de la ciudad</small></div></article><b>→</b><article class="scope-level branch"><span>4</span><div><strong>Sucursal</strong><small>Definiciones y excepciones particulares</small></div></article></div><div class="scope-note"><strong>Prioridad:</strong> Sucursal → Monterrey → Nuevo León → Global. Solo se guarda en cada nivel lo que cambia; lo demás se hereda automáticamente.</div><div class="branch-grid">${branches.map(s=>`<article class="branch-card"><span class="config-badge">Nuevo León · Monterrey</span><strong>${safe(s.nombre)}</strong><small>${countEmployeesByBranch(s.id)} empleados asignados · Hereda de ciudad, estado y global</small></article>`).join('')}</div>`}
function renderGeneralConfig(){$('#generalConfig').innerHTML=`<div class="config-heading"><div><h3>Productos</h3><p><strong>Propietario: Configuración general.</strong> Catálogo único para todas las regiones y sucursales.</p></div></div><div class="config-grid"><article class="config-card"><span class="config-badge">Catálogo global</span><h4>Productos</h4><ul><li>Productos de venta</li><li>Productos de tipo insumo</li><li>Datos y configuración general</li></ul></article><article class="config-card"><span class="config-badge">Información compartida</span><h4>Clientes</h4><p>Expediente único y relación con las sucursales donde recibe atención.</p></article></div>`}
function renderOwnedModules(){$('#stockConfig').innerHTML=`<div class="config-heading"><div><h3>Existencias</h3><p><strong>Propietario: Stock.</strong> Control separado del catálogo de productos.</p></div></div><div class="config-grid"><article class="config-card"><span class="config-badge">Stock</span><h4>Existencias por sucursal</h4><ul><li>Entradas y salidas</li><li>Transferencias</li><li>Ajustes e historial</li></ul></article></div>`;$('#salesConfig').innerHTML=`<div class="config-heading"><div><h3>Servicios y precios</h3><p><strong>Propietario: Ventas.</strong></p></div></div><div class="config-grid"><article class="config-card"><span class="config-badge">Ventas</span><h4>Oferta comercial</h4><ul><li>Servicios y tratamientos</li><li>Listas de precios</li><li>Promociones y paquetes</li></ul></article></div>`;$('#trainingConfig').innerHTML=`<div class="config-heading"><div><h3>Recetas e insumos</h3><p><strong>Propietario: Capacitación.</strong></p></div></div><div class="config-grid"><article class="config-card"><span class="config-badge">Capacitación</span><h4>Tratamientos</h4><ul><li>Receta de insumos por tratamiento</li><li>Cantidades y versiones</li><li>Vigencias y evidencias</li></ul></article></div>`;$('#systemsConfig').innerHTML=`<div class="config-heading"><div><h3>Tickets</h3><p><strong>Propietario: Sistemas.</strong></p></div></div><div class="config-grid"><article class="config-card"><span class="config-badge">Sistemas</span><h4>Soporte por sucursal</h4><ul><li>Solicitud y responsable</li><li>Prioridad y estado</li><li>Reportes y tiempo de solución</li></ul></article></div>`}
function renderAdmin(){renderAdminEmployees();renderAdminDepartments();renderAdminPositions();renderAdminProfiles();renderRegionalConfig();renderGeneralConfig();renderOwnedModules();showConfigType(configType)}
function showConfigType(type){configType=type;document.querySelectorAll('.config-type').forEach(b=>b.classList.toggle('active',b.dataset.configType===type));const sections={rh:'administrativeConfig',security:'securityConfig',regional:'regionalConfig',general:'generalConfig',stock:'stockConfig',sales:'salesConfig',training:'trainingConfig',systems:'systemsConfig'};Object.values(sections).forEach(id=>{$(`#${id}`).hidden=id!==sections[type]});$('#configOverview').hidden=true;if(type==='rh')showAdminSection(adminSection);else $('#newEmployeeBtn').hidden=true}
