document.querySelector('.admin-tabs').onclick=e=>{const b=e.target.closest('[data-admin-section]');if(b)showAdminSection(b.dataset.adminSection)};
$('#adminProfiles').onclick=e=>{const button=e.target.closest('[data-open-profile]');if(!button)return;currentProfile=button.dataset.openProfile;$('#profileSelect').value=currentProfile;saveLocal();showView('permissions');render()};
function fillEmployeeOptions(e={}){$('#employeeDepartment').innerHTML='<option value="">Sin departamento</option>'+adminData.departamentos.map(x=>adminOption(x.id,x.nombre,e.departamento_id)).join('');$('#employeePosition').innerHTML='<option value="">Sin puesto</option>'+adminData.puestos.map(x=>adminOption(x.id,x.nombre,e.puesto_id)).join('');$('#employeeBranch').innerHTML='<option value="">Sin sucursal</option>'+adminData.sucursales.map(x=>adminOption(x.id,x.nombre,e.sucursal_id)).join('');$('#employeeProfile').innerHTML='<option value="">Sin perfil</option>'+adminData.perfiles.map(x=>adminOption(x.id,x.nombre,e.perfil_id)).join('')}
function openEmployee(id=''){const e=adminData.empleados.find(x=>x.id===id)||{};$('#employeeDialogTitle').textContent=id?'Editar empleado':'Nuevo empleado';$('#employeeId').value=e.id||'';$('#employeeNumber').value=e.numero_empleado||'';$('#employeeNames').value=e.nombres||'';$('#employeeLastName').value=e.apellido_paterno||'';$('#employeeSecondLastName').value=e.apellido_materno||'';$('#employeeEmail').value=e.correo||'';$('#employeePhone').value=e.telefono||'';$('#employeeState').value=e.estado||'ACTIVO';fillEmployeeOptions(e);$('#employeeDialog').showModal()}
$('#newEmployeeBtn').onclick=()=>openEmployee();$('#adminEmployees').onclick=e=>{const b=e.target.closest('[data-edit-employee]');if(b)openEmployee(b.dataset.editEmployee);if(e.target.closest('[data-clear-employee-filters]')){employeeFilters={search:'',department:'',branch:'',status:''};renderAdminEmployees()}};$('#adminEmployees').onchange=e=>{const f=e.target.closest('[data-employee-filter]');if(f){employeeFilters[f.dataset.employeeFilter]=f.value;renderAdminEmployees()}};$('#adminEmployees').oninput=e=>{const f=e.target.closest('[data-employee-filter="search"]');if(f){employeeFilters.search=f.value;renderAdminEmployees();const next=$('#adminEmployees').querySelector('[data-employee-filter="search"]');next.focus();next.setSelectionRange(next.value.length,next.value.length)}};
$('#employeeForm').onsubmit=async e=>{e.preventDefault();const btn=$('#saveEmployeeBtn');btn.disabled=true;btn.textContent='Guardando…';const args={p_id:$('#employeeId').value||null,p_numero_empleado:$('#employeeNumber').value.trim(),p_nombres:$('#employeeNames').value.trim(),p_apellido_paterno:$('#employeeLastName').value.trim()||null,p_apellido_materno:$('#employeeSecondLastName').value.trim()||null,p_correo:$('#employeeEmail').value.trim()||null,p_telefono:$('#employeePhone').value.trim()||null,p_estado:$('#employeeState').value,p_departamento_id:$('#employeeDepartment').value||null,p_puesto_id:$('#employeePosition').value||null,p_sucursal_id:$('#employeeBranch').value||null,p_perfil_id:$('#employeeProfile').value||null};const {error}=await appCore.admin.saveEmployee(args);btn.disabled=false;btn.textContent='Guardar empleado';if(error){toast('No se pudo guardar: '+error.message);return}$('#employeeDialog').close();adminLoaded=false;await loadAdmin(true);toast('Empleado guardado en la nube')};
function openCatalog(type,id=''){const rows=type==='department'?adminData.departamentos:adminData.puestos,x=rows.find(r=>r.id===id)||{};$('#catalogType').value=type;$('#catalogId').value=x.id||'';$('#catalogCode').value=x.codigo||'';$('#catalogName').value=x.nombre||'';$('#catalogDescription').value=x.descripcion||'';$('#catalogClassification').value=x.clasificacion||'ADMINISTRATIVO';$('#catalogDepartment').innerHTML='<option value="">Sin departamento</option>'+adminData.departamentos.map(d=>adminOption(d.id,d.nombre,x.departamento_id)).join('');document.querySelector('.department-only').hidden=type!=='department';document.querySelectorAll('.position-only').forEach(el=>el.hidden=type!=='position');$('#catalogKicker').textContent=type==='department'?'Organización':'Plantilla laboral';$('#catalogTitle').textContent=`${id?'Editar':'Nuevo'} ${type==='department'?'departamento':'puesto'}`;$('#catalogDialog').showModal()}
['adminDepartments','adminPositions'].forEach(id=>{$(`#${id}`).onclick=e=>{const n=e.target.closest('[data-new-catalog]');if(n)openCatalog(n.dataset.newCatalog);const d=e.target.closest('[data-edit-department]');if(d)openCatalog('department',d.dataset.editDepartment);const p=e.target.closest('[data-edit-position]');if(p)openCatalog('position',p.dataset.editPosition)}});
$('#catalogForm').onsubmit=async e=>{e.preventDefault();const type=$('#catalogType').value,common={p_id:$('#catalogId').value||null,p_codigo:$('#catalogCode').value.trim(),p_nombre:$('#catalogName').value.trim()};const args=type==='department'?{...common,p_descripcion:$('#catalogDescription').value.trim()||null}:{...common,p_clasificacion:$('#catalogClassification').value,p_departamento_id:$('#catalogDepartment').value||null};const btn=$('#saveCatalogBtn');btn.disabled=true;btn.textContent='Guardando…';const {error}=await appCore.admin.saveCatalog(type,args);btn.disabled=false;btn.textContent='Guardar';if(error){toast('No se pudo guardar: '+error.message);return}$('#catalogDialog').close();adminLoaded=false;await loadAdmin(true);toast('Información guardada en la nube')};
render();
initCloud();
